insert into disease_master (code, name, category, signs, first_actions) values ('IBD', 'Gumboro (Infectious bursal disease)', 'viral', 'Ruffled feathers, whitish diarrhoea, vent pecking, 3-6 week chicks', 'Electrolytes + vitamins in water, reduce protein 2 days, call vet');
insert into disease_master (code, name, category, signs, first_actions) values ('COCCI', 'Coccidiosis', 'protozoal', 'Bloody droppings, huddling, pale comb, poor growth', 'Anticoccidial in water (amprolium/toltrazuril), dry litter, call vet');
insert into disease_master (code, name, category, signs, first_actions) values ('CRD', 'Chronic respiratory disease (Mycoplasma)', 'bacterial', 'Sneezing, nasal discharge, swollen face, rales', 'Improve ventilation, tylosin/tiamulin as prescribed, check ammonia');
insert into disease_master (code, name, category, signs, first_actions) values ('ECOLI', 'Colibacillosis (E. coli)', 'bacterial', 'Omphalitis in chicks, airsacculitis, pericarditis on post-mortem', 'Water sanitation, antibiotic as per sensitivity, brooding hygiene');
insert into disease_master (code, name, category, signs, first_actions) values ('HEAT', 'Heat stress', 'metabolic', 'Panting, wings spread, drop in feed intake, mortality in afternoons', 'Cool water with electrolytes, foggers, reduce stocking, feed at night');
insert into disease_master (code, name, category, signs, first_actions) values ('FP', 'Fowl pox', 'viral', 'Scabs on comb/wattle, diphtheritic lesions in mouth', 'Vaccinate contact birds, iodine on lesions, mosquito control');
insert into disease_master (code, name, category, signs, first_actions) values ('MAREK', 'Marek’s disease', 'viral', 'Leg paralysis (one forward one back), grey eye, tumours', 'Cull affected, check vaccination at hatchery, biosecurity');
insert into disease_master (code, name, category, signs, first_actions) values ('NORMAL', 'No disease detected', 'none', 'Normal droppings and posture', 'Continue monitoring');
insert into disease_master (code, name, category, signs, first_actions) values ('OTHER', 'Other / unknown', 'other', 'Unspecified', 'Record photo, call vet');
